from typing import List
class Solution:
    def maximumSubtreeSize(self, edges: List[List[int]], colors: List[int]) -> int:
        n = len(colors)
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)
        size = [1] * n
        uni = [True] * n
        ans = 1
        stack = [(0, -1, False)]
        while stack:
            v, p, processed = stack.pop()
            if not processed:
                stack.append((v, p, True))
                for w in adj[v]:
                    if w != p:
                        stack.append((w, v, False))
            else:
                for w in adj[v]:
                    if w == p: continue
                    if uni[w] and colors[w] == colors[v]:
                        size[v] += size[w]
                    else:
                        uni[v] = False
                if uni[v]:
                    ans = max(ans, size[v])
        return ans

