class Solution {
    public int maximumSubtreeSize(int[][] edges, int[] colors) {
        int n = colors.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; ++i) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        int[] size = new int[n];
        java.util.Arrays.fill(size, 1);
        boolean[] uni = new boolean[n];
        java.util.Arrays.fill(uni, true);
        int ans = 1;
        Deque<int[]> st = new ArrayDeque<>();
        st.push(new int[]{0, -1, 0});
        while (!st.isEmpty()) {
            int[] top = st.pop();
            int v = top[0], p = top[1], done = top[2];
            if (done == 0) {
                st.push(new int[]{v, p, 1});
                for (int w : adj.get(v)) if (w != p) st.push(new int[]{w, v, 0});
            } else {
                for (int w : adj.get(v)) {
                    if (w == p) continue;
                    if (uni[w] && colors[w] == colors[v]) size[v] += size[w];
                    else uni[v] = false;
                }
                if (uni[v]) ans = Math.max(ans, size[v]);
            }
        }
        return ans;
    }
}

