var maximumSubtreeSize = function(edges, colors) {
    const n = colors.length;
    const adj = Array.from({length: n}, () => []);
    for (const [u, v] of edges) { adj[u].push(v); adj[v].push(u); }
    const size = new Array(n).fill(1);
    const uni = new Array(n).fill(true);
    let ans = 1;
    const st = [[0, -1, false]];
    while (st.length) {
        const [v, p, done] = st.pop();
        if (!done) {
            st.push([v, p, true]);
            for (const w of adj[v]) if (w !== p) st.push([w, v, false]);
        } else {
            for (const w of adj[v]) {
                if (w === p) continue;
                if (uni[w] && colors[w] === colors[v]) size[v] += size[w];
                else uni[v] = false;
            }
            if (uni[v]) ans = Math.max(ans, size[v]);
        }
    }
    return ans;
};

